{
  "name": "المنظم الذكي (Smart Organizer)",
  "description": "منظم مهام ذكي يعتمد على نماذج إنتاجية عالمية مثل مصفوفة أيزنهاور وموسكو، مدعوم بالذكاء الاصطناعي لتصنيف المهام تلقائيًا."
}

export interface Task {
  id: string;
  title: string;
  category: string; // The specific bucket (e.g., "urgent_important", "must_have")
  reasoning?: string; // AI's explanation
  completed: boolean;
  createdAt: number;
}

export enum Methodology {
  Eisenhower = 'EISENHOWER',
  Pareto = 'PARETO',
  GTD = 'GTD',
  TimeBlocking = 'TIME_BLOCKING',
  ActionPriority = 'ACTION_PRIORITY',
  Parkinson = 'PARKINSON',
  MoSCoW = 'MOSCOW',
  IvyLee = 'IVY_LEE',
  EatThatFrog = 'EAT_THAT_FROG',
  ABCDE = 'ABCDE',
  TwoMinute = 'TWO_MINUTE',
  Batching = 'BATCHING'
}

export interface AIReponse {
  category: string;
  reasoning: string;
  priorityScore?: number; // For sorting if needed
}

export interface ViewConfig {
  id: Methodology;
  title: string;
  description: string;
  path: string;
  type: 'matrix' | 'kanban' | 'list' | 'custom';
  categories: { key: string; label: string; color: string; description?: string }[];
  aiSystemInstruction: string;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Methodology, AIReponse } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

// Define the response schema for the AI to ensure consistent JSON
const taskSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    category: {
      type: Type.STRING,
      description: "The category ID that best fits the task based on the methodology.",
    },
    reasoning: {
      type: Type.STRING,
      description: "A short explanation in Arabic of why this category was chosen.",
    },
    priorityScore: {
      type: Type.NUMBER,
      description: "A score from 1-100 indicating importance/urgency",
    }
  },
  required: ["category", "reasoning"],
};

export const classifyTask = async (
  taskText: string,
  methodology: Methodology,
  validCategories: string[]
): Promise<AIReponse> => {
  if (!apiKey) {
    console.error("API Key missing");
    return { category: validCategories[0], reasoning: "API Key missing" };
  }

  const modelId = 'gemini-3-flash-preview'; 

  const prompt = `
    انت مساعد ذكي لتنظيم المهام. المستخدم يريد تنظيم مهمة باستخدام منهجية: ${methodology}.
    المهمة هي: "${taskText}".

    التصنيفات المتاحة هي: [${validCategories.join(', ')}].

    قم بتحليل المهمة واختيار التصنيف الأنسب لها من القائمة أعلاه.
    اكتب السبب باللغة العربية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: taskSchema,
        systemInstruction: "أنت خبير في الإنتاجية وإدارة الوقت. رد دائمًا بتنسيق JSON.",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const result = JSON.parse(text) as AIReponse;

    // Fallback if AI hallucinates a category not in the list
    if (!validCategories.includes(result.category)) {
        return { ...result, category: validCategories[0] };
    }

    return result;
  } catch (error) {
    console.error("Gemini classification error:", error);
    return {
      category: validCategories[0],
      reasoning: "حدث خطأ في الاتصال بالذكاء الاصطناعي، تم الوضع في التصنيف الافتراضي.",
    };
  }
};

import React, { useState } from 'react';
import { Sparkles, Loader2, Plus } from 'lucide-react';
import { classifyTask } from '../services/geminiService';
import { Methodology, Task } from '../types';

interface SmartInputProps {
  methodology: Methodology;
  validCategories: string[];
  onTaskAdded: (task: Task) => void;
}

export const SmartInput: React.FC<SmartInputProps> = ({ methodology, validCategories, onTaskAdded }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    setLoading(true);
    try {
      const result = await classifyTask(input, methodology, validCategories);

      const newTask: Task = {
        id: crypto.randomUUID(),
        title: input,
        category: result.category,
        reasoning: result.reasoning,
        completed: false,
        createdAt: Date.now()
      };

      onTaskAdded(newTask);
      setInput('');
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="w-full relative mb-6">
      <div className="relative flex items-center">
        <div className="absolute right-4 text-teal">
            {loading ? <Loader2 className="animate-spin h-5 w-5" /> : <Sparkles className="h-5 w-5" />}
        </div>
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="اكتب مهمة جديدة... (مثال: الرد على بريد المدير العاجل)"
          className="w-full pr-12 pl-14 py-4 rounded-xl bg-white shadow-sm border-2 border-transparent focus:border-teal text-navy placeholder-gray-400 outline-none transition-all text-lg"
          disabled={loading}
        />
        <button
            type="submit"
            disabled={loading || !input.trim()}
            className="absolute left-2 bg-navy hover:bg-teal text-white p-2 rounded-lg transition-colors disabled:opacity-50"
        >
            <Plus className="h-5 w-5" />
        </button>
      </div>
      {loading && (
        <p className="text-sm text-teal mt-2 text-center animate-pulse">جاري تحليل المهمة وتصنيفها باستخدام Gemini AI...</p>
      )}
    </form>
  );
};

import React from 'react';
import { CheckCircle2, Circle, Trash2, Info } from 'lucide-react';
import { Task } from '../types';

interface TaskCardProps {
  task: Task;
  onDelete: (id: string) => void;
  onToggle: (id: string) => void;
  colorClass?: string;
}

export const TaskCard: React.FC<TaskCardProps> = ({ task, onDelete, onToggle, colorClass = "border-l-4 border-teal" }) => {
  return (
    <div className={`bg-white p-3 rounded-lg shadow-sm mb-3 group hover:shadow-md transition-shadow relative ${colorClass}`}>
      <div className="flex items-start justify-between">
        <div className="flex items-start gap-3 flex-1">
          <button 
            onClick={() => onToggle(task.id)}
            className="mt-1 text-gray-400 hover:text-teal transition-colors"
          >
            {task.completed ? <CheckCircle2 className="h-5 w-5 text-teal" /> : <Circle className="h-5 w-5" />}
          </button>

          <div className="flex-1">
            <h3 className={`font-medium text-navy ${task.completed ? 'line-through text-gray-400' : ''}`}>
              {task.title}
            </h3>
            {task.reasoning && (
              <div className="flex items-start gap-1 mt-1 text-xs text-gray-500 bg-gray-50 p-1.5 rounded">
                <Info className="h-3 w-3 mt-0.5 flex-shrink-0" />
                <p>{task.reasoning}</p>
              </div>
            )}
          </div>
        </div>

        <button 
          onClick={() => onDelete(task.id)}
          className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
        >
          <Trash2 className="h-4 w-4" />
        </button>
      </div>
    </div>
  );
};

