import React, { useState, useEffect } from 'react';
import { ViewConfig, Task } from '../types';
import { SmartInput } from '../components/SmartInput';
import { TaskCard } from '../components/TaskCard';
import { HelpCircle } from 'lucide-react';

interface GenericBoardProps {
  config: ViewConfig;
}

export const GenericBoard: React.FC<GenericBoardProps> = ({ config }) => {
  const [tasks, setTasks] = useState<Task[]>([]);

  // Load tasks specific to this view from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(`tasks_${config.id}`);
    if (saved) {
      setTasks(JSON.parse(saved));
    } else {
        setTasks([]);
    }
  }, [config.id]);

  // Save tasks to local storage whenever they change
  useEffect(() => {
    localStorage.setItem(`tasks_${config.id}`, JSON.stringify(tasks));
  }, [tasks, config.id]);

  const addTask = (task: Task) => {
    setTasks(prev => [task, ...prev]);
  };

  const removeTask = (id: string) => {
    setTasks(prev => prev.filter(t => t.id !== id));
  };

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  // Renderers
  const renderMatrix = () => {
    // 2x2 Grid for Eisenhower and Action Priority
    return (
        <div className="flex flex-col h-full">
            {config.matrixLabels && (
              <div className="flex justify-around mb-2 text-sm font-bold text-teal/80 px-4 md:px-0">
                 <span className="w-1/2 text-center md:pr-4">{config.matrixLabels.x[0]}</span>
                 <span className="w-1/2 text-center md:pl-4">{config.matrixLabels.x[1]}</span>
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 h-full relative">
                {/* Visual Axis Indicator for Large Screens could go here, but omitted for simplicity */}
                {config.categories.map((cat, idx) => (
                    <div key={cat.key} className={`rounded-xl p-4 min-h-[300px] border-2 ${cat.color} bg-white/50 backdrop-blur-sm relative flex flex-col transition-all hover:bg-white/80`}>
                        <div className="flex justify-between items-start mb-4 border-b pb-2">
                            <div>
                                <h3 className="font-bold text-navy text-lg">{cat.label}</h3>
                                <p className="text-xs text-gray-500 mt-1">{cat.description}</p>
                            </div>
                            <span className="text-xs bg-white px-2 py-1 rounded-full shadow-sm text-gray-500 font-mono">
                                {tasks.filter(t => t.category === cat.key).length}
                            </span>
                        </div>
                        <div className="flex-1 overflow-y-auto pr-1">
                            {tasks.filter(t => t.category === cat.key).map(task => (
                                <TaskCard key={task.id} task={task} onDelete={removeTask} onToggle={toggleTask} />
                            ))}
                            {tasks.filter(t => t.category === cat.key).length === 0 && (
                                <div className="h-full flex items-center justify-center opacity-20">
                                    <div className="text-4xl text-gray-400">+</div>
                                </div>
                            )}
                        </div>
                    </div>
                ))}
            </div>
            {config.matrixLabels && (
              <div className="hidden md:flex flex-col absolute -left-8 top-1/2 transform -translate-y-1/2 h-full justify-around text-sm font-bold text-teal/80 py-20 pointer-events-none">
                 <span className="-rotate-90 whitespace-nowrap">{config.matrixLabels.y[0]}</span>
                 <span className="-rotate-90 whitespace-nowrap">{config.matrixLabels.y[1]}</span>
              </div>
            )}
        </div>
    );
  };

  const renderKanban = () => {
    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 overflow-x-auto pb-4">
            {config.categories.map((cat) => (
                <div key={cat.key} className="flex flex-col bg-white rounded-xl shadow-sm border border-gray-100 min-w-[250px]">
                    <div className={`p-4 border-b-4 ${cat.color} rounded-t-xl bg-gray-50`}>
                        <h3 className="font-bold text-navy">{cat.label}</h3>
                        <p className="text-xs text-gray-500 mt-1 min-h-[40px]">{cat.description}</p>
                    </div>
                    <div className="p-3 flex-1 min-h-[400px]">
                         {tasks.filter(t => t.category === cat.key).map(task => (
                            <TaskCard key={task.id} task={task} onDelete={removeTask} onToggle={toggleTask} colorClass={`border-r-4 ${cat.color.replace('border-', 'border-l-')}`} />
                        ))}
                         {tasks.filter(t => t.category === cat.key).length === 0 && (
                             <div className="text-center text-gray-300 mt-10 text-sm">لا توجد مهام</div>
                         )}
                    </div>
                </div>
            ))}
        </div>
    );
  };

  const renderList = () => {
     // For Ivy Lee (Limited list) or simple grouping
     return (
         <div className="max-w-3xl mx-auto space-y-8">
             {config.categories.map((cat) => {
                 const catTasks = tasks.filter(t => t.category === cat.key);
                 return (
                    <div key={cat.key} className="bg-white rounded-xl shadow-sm p-6 relative overflow-hidden">
                         <div className={`absolute top-0 right-0 w-1 h-full ${cat.color.replace('border-', 'bg-')}`}></div>
                         <div className={`flex items-start gap-4 mb-6 pb-3 border-b border-gray-100`}>
                             <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-bold shrink-0 ${cat.color.replace('border-', 'bg-')}`}>
                                {catTasks.length}
                             </div>
                             <div>
                                <h3 className="font-bold text-xl text-navy">{cat.label}</h3>
                                <p className="text-sm text-gray-500">{cat.description}</p>
                             </div>
                         </div>
                         <div className="space-y-3">
                             {catTasks.map(task => (
                                 <TaskCard key={task.id} task={task} onDelete={removeTask} onToggle={toggleTask} />
                             ))}
                             {catTasks.length === 0 && <p className="text-gray-400 italic text-center py-4">أضف مهام لهذه القائمة</p>}
                         </div>
                    </div>
                 )
             })}
         </div>
     )
  };

  return (
    <div className="h-full flex flex-col relative">
      <header className="mb-8">
        <div className="flex items-center gap-2 text-teal mb-2">
            <h2 className="text-3xl font-bold text-navy">{config.title}</h2>
            <div className="group relative z-50">
                <HelpCircle className="w-5 h-5 cursor-help text-muted-teal hover:text-navy" />
                <div className="absolute top-0 right-8 w-72 p-4 bg-navy text-white text-sm rounded-lg shadow-xl opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50 leading-relaxed">
                    {config.description}
                </div>
            </div>
        </div>
        <p className="text-gray-600 max-w-3xl leading-relaxed">{config.description}</p>
      </header>

      <SmartInput 
        methodology={config.id} 
        validCategories={config.categories.map(c => c.key)}
        onTaskAdded={addTask}
      />

      <div className="flex-1 mt-6 overflow-y-auto pb-10">
        {config.type === 'matrix' && renderMatrix()}
        {config.type === 'kanban' && renderKanban()}
        {config.type === 'list' && renderList()}
      </div>
    </div>
  );
};

