import React, { useState, useEffect } from 'react';
import { ViewConfig, Task } from '../types';
import { SmartInput } from '../components/SmartInput';
import { TaskCard } from '../components/TaskCard';
import { HelpCircle } from 'lucide-react';

interface GenericBoardProps {
  config: ViewConfig;
}

export const GenericBoard: React.FC<GenericBoardProps> = ({ config }) => {
  const [tasks, setTasks] = useState<Task[]>([]);

  useEffect(() => {
    const saved = localStorage.getItem(`tasks-${config.id}`);
    if (saved) {
      try {
        setTasks(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse tasks", e);
        setTasks([]);
      }
    } else {
      setTasks([]);
    }
  }, [config.id]);

  useEffect(() => {
    if (tasks.length > 0) {
        localStorage.setItem(`tasks-${config.id}`, JSON.stringify(tasks));
    } else {
        localStorage.setItem(`tasks-${config.id}`, JSON.stringify([]));
    }
  }, [tasks, config.id]);

  const handleTaskAdded = (task: Task) => {
    setTasks(prev => [task, ...prev]);
  };

  const handleToggle = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const handleDelete = (id: string) => {
    setTasks(prev => prev.filter(t => t.id !== id));
  };

  const getTasksByCategory = (categoryKey: string) => {
    return tasks.filter(t => t.category === categoryKey);
  };

  const getTaskColorClass = (catColor: string) => {
    const borderColor = catColor.split(' ').find(c => c.startsWith('border-')) || 'border-teal';
    return `border-l-4 ${borderColor}`;
  };

  const renderContent = () => {
    if (config.type === 'matrix') {
      return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 h-full pb-20">
          {config.categories.map((cat) => (
            <div
              key={cat.key}
              className={`rounded-xl border-t-4 p-4 bg-white shadow-sm min-h-[200px] ${
                cat.color.split(' ').find((c) => c.startsWith('border-')) || 'border-gray-200'
              } bg-opacity-50`}
            >
              <h3 className="font-bold text-lg mb-2 flex items-center justify-between text-navy">
                {cat.label}
                <span className="text-xs font-normal text-gray-500 bg-white px-2 py-1 rounded-full shadow-sm border">
                  {getTasksByCategory(cat.key).length}
                </span>
              </h3>
              {cat.description && (
                <p className="text-xs text-gray-500 mb-4 min-h-[32px]">{cat.description}</p>
              )}
              <div className="space-y-2">
                {getTasksByCategory(cat.key).map((task) => (
                  <TaskCard
                    key={task.id}
                    task={task}
                    onToggle={handleToggle}
                    onDelete={handleDelete}
                    colorClass={getTaskColorClass(cat.color)}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      );
    }

    if (config.type === 'kanban') {
      return (
        <div className="flex flex-col md:flex-row gap-4 overflow-x-auto pb-6 h-full items-start">
          {config.categories.map((cat) => (
            <div
              key={cat.key}
              className="flex-shrink-0 w-full md:w-80 rounded-xl bg-gray-50 p-4 border border-gray-200 shadow-sm max-h-full overflow-y-auto"
            >
              <h3
                className={`font-bold text-lg mb-1 pb-2 border-b-2 ${
                  cat.color.split(' ').find((c) => c.startsWith('border-')) || 'border-teal'
                } flex items-center justify-between text-navy`}
              >
                {cat.label}
                <span className="text-xs font-normal text-gray-600 bg-gray-200 px-2 py-1 rounded-full">
                  {getTasksByCategory(cat.key).length}
                </span>
              </h3>
              {cat.description && (
                <p className="text-xs text-gray-500 mb-3 mt-2">{cat.description}</p>
              )}
              <div className="space-y-2 mt-4">
                {getTasksByCategory(cat.key).map((task) => (
                  <TaskCard
                    key={task.id}
                    task={task}
                    onToggle={handleToggle}
                    onDelete={handleDelete}
                    colorClass={getTaskColorClass(cat.color)}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      );
    }

    // List view
    return (
      <div className="space-y-8 max-w-4xl mx-auto pb-20">
        {config.categories.map((cat) => (
          <div key={cat.key} className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3
              className={`font-bold text-xl mb-2 flex items-center gap-3 text-navy`}
            >
              <div
                className={`w-2 h-8 rounded-full ${
                  cat.color.split(' ').find((c) => c.startsWith('border-'))?.replace('border-', 'bg-') ||
                  'bg-teal'
                }`}
              ></div>
              {cat.label}
              <span className="text-sm font-normal text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">
                ({getTasksByCategory(cat.key).length})
              </span>
            </h3>
            <p className="text-sm text-gray-500 mb-4 pl-5">{cat.description}</p>
            <div className="space-y-2 pl-0 md:pl-5">
              {getTasksByCategory(cat.key).map((task) => (
                <TaskCard
                  key={task.id}
                  task={task}
                  onToggle={handleToggle}
                  onDelete={handleDelete}
                  colorClass={getTaskColorClass(cat.color)}
                />
              ))}
              {getTasksByCategory(cat.key).length === 0 && (
                <p className="text-gray-400 italic text-sm py-4 text-center bg-gray-50 rounded-lg border border-dashed">
                  لا توجد مهام في هذه القائمة
                </p>
              )}
            </div>
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="h-full flex flex-col">
      <div className="mb-8">
        <h2 className="text-3xl font-bold text-navy mb-3 flex items-center gap-2">
          {config.title}
        </h2>
        <div className="text-gray-600 bg-white/60 p-4 rounded-xl border border-white shadow-sm flex items-start gap-3">
          <HelpCircle className="w-6 h-6 text-teal mt-0.5 flex-shrink-0" />
          <p className="leading-relaxed">{config.description}</p>
        </div>
      </div>

      <div className="mb-10 max-w-3xl mx-auto w-full">
        <SmartInput
          methodology={config.id}
          validCategories={config.categories.map((c) => c.key)}
          onTaskAdded={handleTaskAdded}
        />
      </div>

      <div className="flex-1 min-h-0">
        {renderContent()}
      </div>
    </div>
  );
};

