import { Task } from '../types';

class LocalDatabase {
  private getStorageKey(methodologyId: string): string {
    return `tasks-${methodologyId}`;
  }

  getTasks(methodologyId: string): Task[] {
    try {
      const data = localStorage.getItem(this.getStorageKey(methodologyId));
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error("Database read error", e);
      return [];
    }
  }

  saveTasks(methodologyId: string, tasks: Task[]): void {
    try {
      localStorage.setItem(this.getStorageKey(methodologyId), JSON.stringify(tasks));
    } catch (e) {
      console.error("Database write error", e);
    }
  }

  addTask(methodologyId: string, task: Task): Task[] {
    const tasks = this.getTasks(methodologyId);
    const newTasks = [task, ...tasks];
    this.saveTasks(methodologyId, newTasks);
    return newTasks;
  }

  deleteTask(methodologyId: string, taskId: string): Task[] {
    const tasks = this.getTasks(methodologyId);
    const newTasks = tasks.filter(t => t.id !== taskId);
    this.saveTasks(methodologyId, newTasks);
    return newTasks;
  }

  toggleTask(methodologyId: string, taskId: string): Task[] {
    const tasks = this.getTasks(methodologyId);
    const newTasks = tasks.map(t => t.id === taskId ? { ...t, completed: !t.completed } : t);
    this.saveTasks(methodologyId, newTasks);
    return newTasks;
  }
}

export const db = new LocalDatabase();

