import React, { useState } from 'react';
import { Sparkles, Loader2, Plus } from 'lucide-react';
import { classifyTask } from '../services/geminiService';
import { Methodology, Task } from '../types';

interface SmartInputProps {
  methodology: Methodology;
  validCategories: string[];
  onTaskAdded: (task: Task) => void;
  exampleTask?: string;
}

export const SmartInput: React.FC<SmartInputProps> = ({ methodology, validCategories, onTaskAdded, exampleTask }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    setLoading(true);
    try {
      const result = await classifyTask(input, methodology, validCategories);

      const newTask: Task = {
        id: crypto.randomUUID(),
        title: input,
        category: result.category,
        reasoning: result.reasoning,
        completed: false,
        createdAt: Date.now()
      };

      onTaskAdded(newTask);
      setInput('');
    } finally {
      setLoading(false);
    }
  };

  const placeholderText = exampleTask 
    ? `اكتب مهمة جديدة... (مثال: ${exampleTask})`
    : "اكتب مهمة جديدة... (مثال: الرد على بريد المدير العاجل)";

  return (
    <form onSubmit={handleSubmit} className="w-full relative mb-6">
      <div className="relative flex items-center">
        <div className="absolute right-4 text-teal">
            {loading ? <Loader2 className="animate-spin h-5 w-5" /> : <Sparkles className="h-5 w-5" />}
        </div>
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder={placeholderText}
          className="w-full pr-12 pl-14 py-4 rounded-xl bg-white shadow-sm border-2 border-transparent focus:border-teal text-navy placeholder-gray-400 outline-none transition-all text-lg"
          disabled={loading}
        />
        <button
            type="submit"
            disabled={loading || !input.trim()}
            className="absolute left-2 bg-navy hover:bg-teal text-white p-2 rounded-lg transition-colors disabled:opacity-50"
        >
            <Plus className="h-5 w-5" />
        </button>
      </div>
      {loading && (
        <p className="text-sm text-teal mt-2 text-center animate-pulse">جاري تحليل المهمة وتصنيفها باستخدام Gemini AI...</p>
      )}
    </form>
  );
};

import React, { useState, useEffect } from 'react';
import { ViewConfig, Task } from '../types';
import { SmartInput } from '../components/SmartInput';
import { TaskCard } from '../components/TaskCard';
import { HelpCircle } from 'lucide-react';
import { db } from '../services/db';

interface GenericBoardProps {
  config: ViewConfig;
}

export const GenericBoard: React.FC<GenericBoardProps> = ({ config }) => {
  const [tasks, setTasks] = useState<Task[]>([]);

  // Load tasks from DB on mount or config change
  useEffect(() => {
    const loadedTasks = db.getTasks(config.id);
    setTasks(loadedTasks);
  }, [config.id]);

  const handleTaskAdded = (task: Task) => {
    // Add to DB and update state
    const newTasks = db.addTask(config.id, task);
    setTasks(newTasks);
  };

  const handleToggle = (id: string) => {
    // Toggle in DB and update state
    const newTasks = db.toggleTask(config.id, id);
    setTasks(newTasks);
  };

  const handleDelete = (id: string) => {
    // Delete from DB and update state
    const newTasks = db.deleteTask(config.id, id);
    setTasks(newTasks);
  };

  const getTasksByCategory = (categoryKey: string) => {
    return tasks.filter(t => t.category === categoryKey);
  };

  const getTaskColorClass = (catColor: string) => {
    const borderColor = catColor.split(' ').find(c => c.startsWith('border-')) || 'border-teal';
    return `border-l-4 ${borderColor}`;
  };

  // Helper to render individual category boxes
  const renderCategoryBox = (cat: { key: string; label: string; color: string; description?: string }, isMatrixCell = false) => {
    const catTasks = getTasksByCategory(cat.key);
    return (
      <div
        className={`rounded-xl border-t-4 p-4 bg-white shadow-sm h-full flex flex-col ${
            cat.color.split(' ').find((c) => c.startsWith('border-')) || 'border-gray-200'
        } bg-opacity-50`}
      >
        <h3 className="font-bold text-lg mb-2 flex items-center justify-between text-navy">
            {cat.label}
            <span className="text-xs font-normal text-gray-500 bg-white px-2 py-1 rounded-full shadow-sm border">
            {catTasks.length}
            </span>
        </h3>
        {!isMatrixCell && cat.description && (
            <p className="text-xs text-gray-500 mb-4 min-h-[32px]">{cat.description}</p>
        )}
        <div className="space-y-2 overflow-y-auto flex-1 pr-1 custom-scrollbar">
            {catTasks.map((task) => (
            <TaskCard
                key={task.id}
                task={task}
                onToggle={handleToggle}
                onDelete={handleDelete}
                colorClass={getTaskColorClass(cat.color)}
            />
            ))}
            {catTasks.length === 0 && (
                <div className="h-20 flex items-center justify-center text-gray-300 border-2 border-dashed border-gray-100 rounded-lg">
                    <span className="text-2xl opacity-50">+</span>
                </div>
            )}
        </div>
      </div>
    );
  };

  const renderMatrix = () => {
    if (!config.matrixLabels) return renderKanban();

    return (
        <div className="h-full flex flex-col pb-4">
            {/* Mobile: Just list them */}
            <div className="md:hidden flex flex-col gap-4">
                 {config.categories.map(cat => (
                     <div key={cat.key} className="min-h-[250px]">
                         {renderCategoryBox(cat)}
                     </div>
                 ))}
            </div>

            {/* Desktop: Grid */}
            <div className="hidden md:grid gap-4 h-full" style={{
                gridTemplateColumns: 'min-content 1fr 1fr',
                gridTemplateRows: 'min-content 1fr 1fr'
            }}>
                {/* 0,0 Corner */}
                <div></div>

                {/* 0,1 Top Header (Right Column - Not Urgent) */}
                <div className="bg-teal/10 text-teal font-bold text-lg rounded-xl flex items-center justify-center py-2 shadow-sm">
                    {config.matrixLabels.x[0]}
                </div>

                {/* 0,2 Top Header (Left Column - Urgent) */}
                <div className="bg-teal/10 text-teal font-bold text-lg rounded-xl flex items-center justify-center py-2 shadow-sm">
                    {config.matrixLabels.x[1]}
                </div>

                {/* 1,0 Side Header (Top Row - Important) */}
                <div className="bg-teal/10 text-teal font-bold text-lg rounded-xl flex items-center justify-center px-2 w-12 shadow-sm">
                    <span className="-rotate-90 whitespace-nowrap">{config.matrixLabels.y[0]}</span>
                </div>

                {/* 1,1 Cell (Right/Top) */}
                <div className="overflow-hidden">
                    {renderCategoryBox(config.categories[0], true)}
                </div>

                {/* 1,2 Cell (Left/Top) */}
                <div className="overflow-hidden">
                    {renderCategoryBox(config.categories[1], true)}
                </div>

                {/* 2,0 Side Header (Bottom Row - Unimportant) */}
                <div className="bg-teal/10 text-teal font-bold text-lg rounded-xl flex items-center justify-center px-2 w-12 shadow-sm">
                    <span className="-rotate-90 whitespace-nowrap">{config.matrixLabels.y[1]}</span>
                </div>

                {/* 2,1 Cell (Right/Bottom) */}
                <div className="overflow-hidden">
                    {renderCategoryBox(config.categories[2], true)}
                </div>

                {/* 2,2 Cell (Left/Bottom) */}
                <div className="overflow-hidden">
                    {renderCategoryBox(config.categories[3], true)}
                </div>
            </div>
        </div>
    );
  };

  const renderKanban = () => {
    return (
        <div className="flex flex-col md:flex-row gap-4 overflow-x-auto pb-6 h-full">
          {config.categories.map((cat) => (
            <div
              key={cat.key}
              className="flex-shrink-0 w-full md:flex-1 md:min-w-[200px] h-full"
            >
               {renderCategoryBox(cat)}
            </div>
          ))}
        </div>
    );
  };

  const renderContent = () => {
    if (config.type === 'matrix') {
        return renderMatrix();
    }

    if (config.type === 'kanban') {
        return renderKanban();
    }

    // List view
    return (
      <div className="space-y-4 max-w-5xl mx-auto pb-20">
        {config.categories.map((cat) => (
          <div key={cat.key} className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3 className={`font-bold text-xl mb-2 flex items-center gap-3 text-navy`}>
              <div className={`w-2 h-8 rounded-full ${cat.color.split(' ').find((c) => c.startsWith('border-'))?.replace('border-', 'bg-') || 'bg-teal'}`}></div>
              {cat.label}
              <span className="text-sm font-normal text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">
                ({getTasksByCategory(cat.key).length})
