import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Methodology, AIReponse } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

// Define the response schema for the AI to ensure consistent JSON
const taskSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    category: {
      type: Type.STRING,
      description: "The category ID that best fits the task based on the methodology.",
    },
    reasoning: {
      type: Type.STRING,
      description: "A short explanation in Arabic of why this category was chosen.",
    },
    priorityScore: {
      type: Type.NUMBER,
      description: "A score from 1-100 indicating importance/urgency",
    }
  },
  required: ["category", "reasoning"],
};

export const classifyTask = async (
  taskText: string,
  methodology: Methodology,
  validCategories: string[]
): Promise<AIReponse> => {
  if (!apiKey) {
    console.error("API Key missing");
    return { category: validCategories[0], reasoning: "API Key missing" };
  }

  const modelId = 'gemini-3-flash-preview'; 

  const prompt = `
    انت مساعد ذكي لتنظيم المهام. المستخدم يريد تنظيم مهمة باستخدام منهجية: ${methodology}.
    المهمة هي: "${taskText}".

    التصنيفات المتاحة هي: [${validCategories.join(', ')}].

    قم بتحليل المهمة واختيار التصنيف الأنسب لها من القائمة أعلاه.
    اكتب السبب باللغة العربية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: taskSchema,
        systemInstruction: "أنت خبير في الإنتاجية وإدارة الوقت. رد دائمًا بتنسيق JSON.",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const result = JSON.parse(text) as AIReponse;

    // Fallback if AI hallucinates a category not in the list
    if (!validCategories.includes(result.category)) {
        return { ...result, category: validCategories[0] };
    }

    return result;
  } catch (error) {
    console.error("Gemini classification error:", error);
    return {
      category: validCategories[0],
      reasoning: "حدث خطأ في الاتصال بالذكاء الاصطناعي، تم الوضع في التصنيف الافتراضي.",
    };
  }
};

export const chatWithAssistant = async (
  history: { role: string; text: string }[],
  newMessage: string,
  screenContext?: string
): Promise<string> => {
  if (!apiKey) return "عذراً، مفتاح API غير متوفر.";

  // Use Flash Lite for low latency responses
  const modelId = 'gemini-flash-lite-latest';

  try {
    // Transform history to the format expected by the API
    const chatHistory = history.map(msg => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.text }]
    }));

    // If context is provided, inject it as a system message or user context
    let systemInstruction = "أنت مساعد شخصي ذكي وسريع لتنظيم الوقت والمهام. ساعد المستخدم في إيجاد طرق للمذاكرة، تنظيم يومه، أو اختيار منهجية مناسبة. إجاباتك يجب أن تكون مختصرة، مفيدة، وباللغة العربية.";

    if (screenContext) {
      systemInstruction += `\n\n[سياق الشاشة الحالي]: المستخدم ينظر حالياً إلى البيانات التالية على شاشته: ${screenContext}. يمكنك استخدام هذه المعلومات للإجابة على أسئلة المستخدم حول مهامه الحالية.`;
    }

    const chat = ai.chats.create({
      model: modelId,
      history: chatHistory,
      config: {
        systemInstruction: systemInstruction,
      }
    });

    const result = await chat.sendMessage({ message: newMessage });
    return result.text || "لم أتمكن من إنشاء رد.";
  } catch (error) {
    console.error("Chat error:", error);
    return "عذراً، حدث خطأ أثناء الاتصال بالمساعد الذكي.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, Send, X, MessageCircleQuestion, Minimize2 } from 'lucide-react';
import { chatWithAssistant } from '../services/geminiService';
import { useLocation } from 'react-router-dom';
import { METHODOLOGIES } from '../constants';
import { db } from '../services/db';

interface Message {
  role: 'user' | 'model';
  text: string;
}

export const AIChatAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'أهلاً بك! أنا مساعدك التنظيمي السريع. كيف يمكنني مساعدتك في تنظيم وقتك أو دراستك اليوم؟' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const location = useLocation();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  // Function to gather context from the current screen
  const getScreenContext = () => {
    const currentPath = location.pathname;

    // Find if we are on a methodology board
    const currentMethod = Object.values(METHODOLOGIES).find(m => m.path === currentPath);

    if (currentMethod) {
      const tasks = db.getTasks(currentMethod.id);

      // Simplify task data for AI token efficiency
      const simplifiedTasks = tasks.map(t => ({
        title: t.title,
        category: t.category,
        completed: t.completed,
        reasoning: t.reasoning
      }));

      return JSON.stringify({
        pageTitle: currentMethod.title,
        pageDescription: currentMethod.description,
        categories: currentMethod.categories.map(c => ({ key: c.key, label: c.label })),
        currentTasks: simplifiedTasks
      });
    } else if (currentPath === '/') {
        return "المستخدم في الصفحة الرئيسية (Home Page).";
    }

    return "المستخدم يتصفح الموقع بشكل عام.";
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    try {
      const context = getScreenContext();
      const response = await chatWithAssistant(messages, userMessage, context);
      setMessages(prev => [...prev, { role: 'model', text: response }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: 'عذراً، حدث خطأ ما.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Marker Icon */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-6 left-6 z-50 p-4 rounded-full bg-white/20 backdrop-blur-md border border-teal/30 shadow-lg text-teal hover:bg-teal hover:text-white transition-all duration-300 group"
          title="مساعد التنظيم الذكي"
        >
          <Sparkles className="w-6 h-6 animate-pulse group-hover:animate-none" />
          <span className="absolute left-full ml-2 top-1/2 -translate-y-1/2 bg-navy text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
            محادثة سريعة
          </span>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-6 left-6 z-50 w-80 md:w-96 h-[500px] bg-white/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/50 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300">

          {/* Header */}
          <div className="bg-gradient-to-r from-navy to-teal p-4 flex items-center justify-between text-white shadow-md">
            <div className="flex items-center gap-2">
              <Sparkles className="w-5 h-5" />
              <h3 className="font-bold text-sm">المساعد الذكي</h3>
            </div>
            <button 
              onClick={() => setIsOpen(false)}
              className="p-1 hover:bg-white/20 rounded-full transition-colors"
            >
              <Minimize2 className="w-4 h-4" />
            </button>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar bg-cream/30">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                    msg.role === 'user'
                      ? 'bg-teal text-white rounded-br-none'
                      : 'bg-white text-navy border border-gray-100 rounded-bl-none'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white p-3 rounded-2xl rounded-bl-none shadow-sm border border-gray-100 flex gap-1">
                  <div className="w-2 h-2 bg-teal/50 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                  <div className="w-2 h-2 bg-teal/50 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                  <div className="w-2 h-2 bg-teal/50 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <form onSubmit={handleSend} className="p-3 bg-white border-t border-gray-100 flex gap-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="اطلب نصيحة، طريقة تنظيم..."
              className="flex-1 px-4 py-2 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal focus:bg-white text-sm text-navy placeholder-gray-400 transition-all"
            />
            <button
              type="submit"
              disabled={!input.trim() || isLoading}
              className="p-2 bg-teal text-white rounded-xl hover:bg-navy disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
            >
              <Send className="w-5 h-5" />
            </button>
          </form>
        </div>
      )}
    </>
  );
};

import React, { useState, useEffect } from 'react';
