import React, { useState } from 'react';
import { Sparkles, Loader2, Plus, ArrowUp } from 'lucide-react';
import { classifyTask } from '../services/geminiService';
import { Methodology, Task } from '../types';

interface SmartInputProps {
  methodology: Methodology;
  validCategories: string[];
  onTaskAdded: (task: Task) => void;
  exampleTask?: string;
}

export const SmartInput: React.FC<SmartInputProps> = ({ methodology, validCategories, onTaskAdded, exampleTask }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isFocused, setIsFocused] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    setLoading(true);
    try {
      const result = await classifyTask(input, methodology, validCategories);

      const newTask: Task = {
        id: crypto.randomUUID(),
        title: input,
        category: result.category,
        reasoning: result.reasoning,
        completed: false,
        createdAt: Date.now()
      };

      onTaskAdded(newTask);
      setInput('');
    } finally {
      setLoading(false);
    }
  };

  const placeholderText = exampleTask 
    ? `مثال: ${exampleTask}`
    : "اكتب مهمة جديدة... (مثال: الرد على بريد المدير العاجل)";

  return (
    <div className={`
        relative w-full max-w-3xl mx-auto transition-all duration-500 ease-out z-20
        ${isFocused ? 'scale-105' : 'scale-100'}
    `}>
        {/* Glow Effect */}
        <div className={`absolute -inset-1 bg-gradient-to-r from-teal to-blue-500 rounded-2xl blur opacity-20 transition-opacity duration-500 ${isFocused ? 'opacity-40' : 'opacity-0'}`}></div>

        <form onSubmit={handleSubmit} className="relative bg-white rounded-2xl shadow-soft">
            <div className="flex items-center p-2">
                <div className="p-3 text-teal">
                    {loading ? <Loader2 className="animate-spin w-6 h-6" /> : <Sparkles className="w-6 h-6 animate-pulse" />}
                </div>

                <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onFocus={() => setIsFocused(true)}
                    onBlur={() => setIsFocused(false)}
                    placeholder={placeholderText}
                    className="flex-1 bg-transparent border-none outline-none text-lg text-navy placeholder-gray-400 py-3 px-2 font-medium"
                    disabled={loading}
                />

                <button
                    type="submit"
                    disabled={loading || !input.trim()}
                    className={`
                        p-3 rounded-xl transition-all duration-300 flex items-center gap-2
                        ${input.trim() 
                            ? 'bg-navy text-white hover:bg-teal shadow-md translate-x-0 opacity-100' 
                            : 'bg-gray-100 text-gray-400 cursor-not-allowed opacity-50'}
                    `}
                >
                    <span className="hidden md:inline text-sm font-bold">إضافة</span>
                    {input.trim() ? <ArrowUp size={20} /> : <Plus size={20} />}
                </button>
            </div>

            {/* Loading Status Text */}
            <div className={`
                overflow-hidden transition-all duration-300 ease-in-out
                ${loading ? 'max-h-10 opacity-100' : 'max-h-0 opacity-0'}
            `}>
                <div className="px-4 pb-3 text-xs font-medium text-teal flex items-center gap-2">
                    <span className="w-1.5 h-1.5 rounded-full bg-teal animate-ping"></span>
                    جاري التحليل والتصنيف بالذكاء الاصطناعي...
                </div>
            </div>
        </form>
    </div>
  );
};

