import React, { useState, useEffect } from 'react';
import { ViewConfig, Task } from '../types';
import { SmartInput } from '../components/SmartInput';
import { TaskCard } from '../components/TaskCard';
import { HelpCircle, Info } from 'lucide-react';
import { db } from '../services/db';

interface GenericBoardProps {
  config: ViewConfig;
}

export const GenericBoard: React.FC<GenericBoardProps> = ({ config }) => {
  const [tasks, setTasks] = useState<Task[]>([]);

  // Load tasks from DB on mount or config change
  useEffect(() => {
    const loadedTasks = db.getTasks(config.id);
    setTasks(loadedTasks);
  }, [config.id]);

  const handleTaskAdded = (task: Task) => {
    // Add to DB and update state
    const newTasks = db.addTask(config.id, task);
    setTasks(newTasks);
  };

  const handleToggle = (id: string) => {
    // Toggle in DB and update state
    const newTasks = db.toggleTask(config.id, id);
    setTasks(newTasks);
  };

  const handleDelete = (id: string) => {
    // Delete from DB and update state
    const newTasks = db.deleteTask(config.id, id);
    setTasks(newTasks);
  };

  const getTasksByCategory = (categoryKey: string) => {
    return tasks.filter(t => t.category === categoryKey);
  };

  const getTaskColorClass = (catColor: string) => {
    const borderColor = catColor.split(' ').find(c => c.startsWith('border-')) || 'border-teal';
    return `border-l-4 ${borderColor}`;
  };

  // Helper to render individual category boxes
  const renderCategoryBox = (cat: { key: string; label: string; color: string; description?: string }, isMatrixCell = false) => {
    const catTasks = getTasksByCategory(cat.key);
    // Extract base color for subtle background
    const bgClass = cat.color.includes('bg-') ? cat.color.split(' ').find(c => c.startsWith('bg-')) : 'bg-white';
    const borderClass = cat.color.split(' ').find(c => c.startsWith('border-')) || 'border-gray-200';

    return (
      <div
        className={`
            h-full flex flex-col rounded-2xl border transition-all duration-300
            ${isMatrixCell ? 'p-3 shadow-sm hover:shadow-md' : 'p-4 shadow-sm bg-white'}
            ${isMatrixCell ? bgClass + '/30' : 'bg-white'} 
            ${isMatrixCell ? borderClass : 'border-gray-100'}
        `}
      >
        <div className="mb-4">
            <h3 className="font-bold text-lg flex items-center justify-between text-navy">
                <span className="flex items-center gap-2">
                    {!isMatrixCell && <div className={`w-2 h-2 rounded-full ${borderClass.replace('border-', 'bg-')}`}></div>}
                    {cat.label}
                </span>
                <span className={`text-xs font-bold px-2.5 py-1 rounded-lg ${isMatrixCell ? 'bg-white/60' : 'bg-gray-100'} text-gray-600`}>
                    {catTasks.length}
                </span>
            </h3>
            {cat.description && (
                <p className="text-xs text-gray-500 mt-2 leading-relaxed opacity-80">
                    {cat.description}
                </p>
            )}
        </div>

        <div className="space-y-3 overflow-y-auto flex-1 pr-1 custom-scrollbar min-h-[100px]">
            {catTasks.map((task) => (
            <TaskCard
                key={task.id}
                task={task}
                onToggle={handleToggle}
                onDelete={handleDelete}
                colorClass={getTaskColorClass(cat.color)}
            />
            ))}
            {catTasks.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-gray-400 border-2 border-dashed border-gray-300/30 rounded-xl p-4">
                    <span className="text-2xl opacity-30 mb-1">+</span>
                    <span className="text-xs opacity-60">فارغ</span>
                </div>
            )}
        </div>
      </div>
    );
  };

  const renderMatrix = () => {
    if (!config.matrixLabels) return renderKanban();

    return (
        <div className="h-full flex flex-col pb-6">
            {/* Mobile: Just list them */}
            <div className="md:hidden flex flex-col gap-4">
                 {config.categories.map(cat => (
                     <div key={cat.key} className="min-h-[200px]">
                         {renderCategoryBox(cat)}
                     </div>
                 ))}
            </div>

            {/* Desktop: Grid - CORRECTED LAYOUT: Labels on LEFT */}
            <div className="hidden md:grid gap-4 h-full" style={{
                gridTemplateColumns: '50px 1fr 1fr', // Auto for labels, then 2 equal cols
                gridTemplateRows: '50px 1fr 1fr' // Header height, then 2 equal rows
            }}>
                {/* 0,0 - Empty Corner */}
                <div className="col-start-1 row-start-1"></div>

                {/* 0,1 - Top Header 1 (Not Urgent - Right Col?) -> Usually Matrix is Urgent Left, Not Urgent Right */}
                {/* Based on typical Eisenhower: x[0]=Not Urgent (Right?), x[1]=Urgent (Left?) or vice versa depending on config array order */}
                {/* Let's follow the array order: x[0] -> Col 2, x[1] -> Col 3 ?? No, let's look at config. */}
                {/* Config: x: ["غير عاجل", "عاجل"]. Usually we want Urgent on Left. Let's place x[1] (Urgent) in Col 2, x[0] (Not Urgent) in Col 3 */}

                {/* Top Headers */}
                <div className="col-start-2 row-start-1 bg-navy/5 text-navy font-bold rounded-2xl flex items-center justify-center border border-navy/5">
                    {config.matrixLabels.x[1]} {/* Urgent */}
                </div>
                <div className="col-start-3 row-start-1 bg-navy/5 text-navy font-bold rounded-2xl flex items-center justify-center border border-navy/5">
                    {config.matrixLabels.x[0]} {/* Not Urgent */}
                </div>

                {/* Side Header 1 (Important - Top Row) */}
                <div className="col-start-1 row-start-2 bg-navy/5 text-navy font-bold rounded-2xl flex items-center justify-center border border-navy/5 writing-mode-vertical">
                    <span className="-rotate-90 whitespace-nowrap text-sm tracking-widest">{config.matrixLabels.y[0]}</span>
                </div>

                {/* Side Header 2 (Not Important - Bottom Row) */}
                <div className="col-start-1 row-start-3 bg-navy/5 text-navy font-bold rounded-2xl flex items-center justify-center border border-navy/5 writing-mode-vertical">
                    <span className="-rotate-90 whitespace-nowrap text-sm tracking-widest">{config.matrixLabels.y[1]}</span>
                </div>

                {/* Cells Placement */}
                {/* We need to map categories to the correct grid cell based on logic */}
                {/* Assuming: 
                    Cat 0 (decide): Important & Not Urgent -> Row 2, Col 3
                    Cat 1 (do): Important & Urgent -> Row 2, Col 2
                    Cat 2 (delete): Not Important & Not Urgent -> Row 3, Col 3
                    Cat 3 (delegate): Not Important & Urgent -> Row 3, Col 2
                */}

                {/* Important & Urgent (Do) -> Row 2, Col 2 */}
                <div className="col-start-2 row-start-2 overflow-hidden h-full">
                    {renderCategoryBox(config.categories[1], true)}
                </div>

                {/* Important & Not Urgent (Decide) -> Row 2, Col 3 */}
                <div className="col-start-3 row-start-2 overflow-hidden h-full">
                    {renderCategoryBox(config.categories[0], true)}
                </div>

                 {/* Not Important & Urgent (Delegate) -> Row 3, Col 2 */}
                <div className="col-start-2 row-start-3 overflow-hidden h-full">
                    {renderCategoryBox(config.categories[3], true)}
                </div>

                {/* Not Important & Not Urgent (Delete) -> Row 3, Col 3 */}
                <div className="col-start-3 row-start-3 overflow-hidden h-full">
                    {renderCategoryBox(config.categories[2], true)}
                </div>

            </div>
        </div>
    );
  };

  const renderKanban = () => {
    return (
        <div className="flex flex-col md:flex-row gap-6 overflow-x-auto pb-6 h-full px-2">
          {config.categories.map((cat) => (
            <div
              key={cat.key}
              className="flex-shrink-0 w-full md:flex-1 md:min-w-[250px] h-full"
            >
               {renderCategoryBox(cat)}
            </div>
          ))}
        </div>
    );
  };

  const renderList = () => {
      return (
        <div className="space-y-6 max-w-4xl mx-auto pb-20">
            {config.categories.map((cat) => (
            <div key={cat.key} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 overflow-hidden relative group hover:shadow-md transition-shadow">
                <div className={`absolute top-0 left-0 bottom-0 w-1.5 ${cat.color.split(' ').find(c => c.startsWith('bg-'))?.replace('bg-', 'bg-') || 'bg-teal'}`}></div>
                <h3 className={`font-bold text-xl mb-3 flex items-center gap-3 text-navy pl-4`}>
                {cat.label}
                <span className="text-xs font-normal text-gray-400 bg-gray-50 px-2.5 py-1 rounded-full border border-gray-100">
                    {getTasksByCategory(cat.key).length} مهام
                </span>
                </h3>
                <p className="text-sm text-gray-500 mb-6 pl-4 max-w-2xl">{cat.description}</p>
                <div className="space-y-3 pl-0 md:pl-4">
                {getTasksByCategory(cat.key).map((task) => (
                    <TaskCard
                    key={task.id}
                    task={task}
                    onToggle={handleToggle}
                    onDelete={handleDelete}
                    colorClass={getTaskColorClass(cat.color)}
                    />
                ))}
                {getTasksByCategory(cat.key).length === 0 && (
                    <div className="flex flex-col items-center justify-center py-8 bg-gray-50/50 rounded-xl border border-dashed border-gray-200">
                        <p className="text-gray-400 text-sm">لا توجد مهام في هذه القائمة</p>
                    </div>
                )}
                </div>
            </div>
            ))}
        </div>
      );
  }

  const renderContent = () => {
    if (config.type === 'matrix') return renderMatrix();
    if (config.type === 'kanban') return renderKanban();
    return renderList();
  };

  return (
    <div className="h-full flex flex-col">
      <div className="mb-8">
        <h2 className="text-3xl font-extrabold text-navy mb-4 flex items-center gap-3">
            <span className="bg-teal/10 p-2 rounded-xl text-teal">
                 {/* Icon placeholder if needed, using generic for now */}
                 <Info size={24} />
            </span>
            {config.title}
        </h2>
        <div className="text-gray-600 bg-white p-5 rounded-2xl border border-gray-100 shadow-soft flex items-start gap-4">
          <HelpCircle className="w-5 h-5 text-teal mt-1 flex-shrink-0" />
          <p className="leading-relaxed text-sm md:text-base">{config.description}</p>
        </div>
      </div>

      <div className="mb-10 w-full">
        <SmartInput
          methodology={config.id}
          validCategories={config.categories.map((c) => c.key)}
          onTaskAdded={handleTaskAdded}
          exampleTask={config.exampleTask}
        />
      </div>

      <div className="flex-1 min-h-0 relative">
        {renderContent()}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, Send, X, Minimize2, Bot } from 'lucide-react';
import { chatWithAssistant } from '../services/geminiService';
import { useLocation } from 'react-router-dom';
import { METHODOLOGIES } from '../constants';
import { db } from '../services/db';

interface Message {
  role: 'user' | 'model';
  text: string;
}

export const AIChatAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'أهلاً بك! أنا مساعدك التنظيمي السريع. كيف يمكنني مساعدتك في تنظيم وقتك أو دراستك اليوم؟' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const location = useLocation();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  // Function to gather context from the current screen
  const getScreenContext = () => {
    const currentPath = location.pathname;
    const currentMethod = Object.values(METHODOLOGIES).find(m => m.path === currentPath);

    if (currentMethod) {
      const tasks = db.getTasks(currentMethod.id);
      const simplifiedTasks = tasks.map(t => ({
        title: t.title,
        category: t.category,
        completed: t.completed,
        reasoning: t.reasoning
      }));

      return JSON.stringify({
        pageTitle: currentMethod.title,
        pageDescription: currentMethod.description,
        categories: currentMethod.categories.map(c => ({ key: c.key, label: c.label })),
        currentTasks: simplifiedTasks
      });
    } else if (currentPath === '/') {
        return "المستخدم في الصفحة الرئيسية (Home Page).";
    }
    return "المستخدم يتصفح الموقع بشكل عام.";
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    try {
      const context = getScreenContext();
      const response = await chatWithAssistant(messages, userMessage, context);
      setMessages(prev => [...prev, { role: 'model', text: response }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: 'عذراً، حدث خطأ ما.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Marker Icon */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-8 left-8 z-50 group flex items-center justify-center"
          title="مساعد التنظيم الذكي"
        >
          <div className="absolute inset-0 bg-teal rounded-full animate-ping opacity-20 group-hover:opacity-40"></div>
          <div className="relative bg-white/80 backdrop-blur-md border border-teal/20 p-4 rounded-full shadow-lg text-teal group-hover:scale-110 transition-transform duration-300">
             <Sparkles className="w-6 h-6" />
          </div>
          <span className="absolute left-full ml-3 bg-navy text-white text-xs px-3 py-1.5 rounded-lg opacity-0 group-hover:opacity-100 transition-all duration-300 translate-x-2 group-hover:translate-x-0 whitespace-nowrap shadow-md">
            محادثة سريعة
          </span>
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-6 left-6 z-50 w-[90vw] md:w-[400px] h-[550px] bg-white/95 backdrop-blur-2xl rounded-3xl shadow-2xl border border-white/50 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300 ring-1 ring-black/5">

          {/* Header */}
          <div className="bg-navy p-4 flex items-center justify-between text-white shadow-md relative overflow-hidden">
             <div className="absolute inset-0 bg-gradient-to-r from-teal/20 to-transparent"></div>
            <div className="flex items-center gap-3 relative z-10">
              <div className="bg-white/10 p-2 rounded-xl">
                  <Bot className="w-5 h-5 text-teal-light" />
              </div>
              <div>
                <h3 className="font-bold text-sm">المساعد الذكي</h3>
                <p className="text-[10px] text-gray-300 flex items-center gap-1">
                    <span className="w-1.5 h-1.5 bg-green-400 rounded-full"></span>
                    متصل الآن
                </p>
              </div>
            </div>
            <button 
              onClick={() => setIsOpen(false)}
              className="p-2 hover:bg-white/10 rounded-full transition-colors relative z-10"
            >
              <Minimize2 className="w-4 h-4" />
            </button>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar bg-gray-50/50">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}
              >
                {/* Avatar */}
                <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 mt-1 ${msg.role === 'user' ? 'bg-teal text-white' : 'bg-navy text-white'}`}>
                    {msg.role === 'user' ? <span className="text-xs font-bold">أنت</span> : <Sparkles size={12} />}
                </div>

                {/* Bubble */}
                <div
                  className={`max-w-[80%] p-3.5 rounded-2xl text-sm leading-relaxed shadow-sm ${
                    msg.role === 'user'
                      ? 'bg-teal text-white rounded-tr-none'
                      : 'bg-white text-navy border border-gray-100 rounded-tl-none'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-3">
                 <div className="w-8 h-8 rounded-full bg-navy text-white flex items-center justify-center flex-shrink-0 mt-1">
                    <Sparkles size={12} />
                </div>
                <div className="bg-white p-4 rounded-2xl rounded-tl-none shadow-sm border border-gray-100 flex gap-1.5 items-center">
                  <div className="w-2 h-2 bg-teal/40 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                  <div className="w-2 h-2 bg-teal/40 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                  <div className="w-2 h-2 bg-teal/40 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <form onSubmit={handleSend} className="p-4 bg-white border-t border-gray-100">
            <div className="relative flex items-center gap-2">
                <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="اسألني أي شيء..."
                className="flex-1 pl-4 pr-4 py-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal focus:bg-white text-sm text-navy placeholder-gray-400 transition-all"
                />
                <button
                type="submit"
                disabled={!input.trim() || isLoading}
                className="absolute left-2 p-2 bg-teal text-white rounded-lg hover:bg-navy disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm hover:scale-105 active:scale-95"
                >
                <Send className="w-4 h-4" />
                </button>
            </div>
          </form>
        </div>
      )}
    </>
  );
};

