import React, { useState, useEffect, useRef } from 'react';
import { ViewConfig, Task } from '../types';
import { SmartInput } from '../components/SmartInput';
import { TaskCard } from '../components/TaskCard';
import { HelpCircle, Info, X } from 'lucide-react';
import { db } from '../services/db';

interface GenericBoardProps {
  config: ViewConfig;
}

export const GenericBoard: React.FC<GenericBoardProps> = ({ config }) => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [showDescription, setShowDescription] = useState(false);
  const descriptionRef = useRef<HTMLDivElement>(null);

  // Load tasks from DB on mount or config change
  useEffect(() => {
    const loadedTasks = db.getTasks(config.id);
    setTasks(loadedTasks);
    setShowDescription(false); // Reset description visibility on route change
  }, [config.id]);

  // Close description when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (descriptionRef.current && !descriptionRef.current.contains(event.target as Node)) {
        setShowDescription(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleTaskAdded = (task: Task) => {
    // Add to DB and update state
    const newTasks = db.addTask(config.id, task);
    setTasks(newTasks);
  };

  const handleToggle = (id: string) => {
    // Toggle in DB and update state
    const newTasks = db.toggleTask(config.id, id);
    setTasks(newTasks);
  };

  const handleDelete = (id: string) => {
    // Delete from DB and update state
    const newTasks = db.deleteTask(config.id, id);
    setTasks(newTasks);
  };

  const getTasksByCategory = (categoryKey: string) => {
    return tasks.filter(t => t.category === categoryKey);
  };

  const getTaskColorClass = (catColor: string) => {
    const borderColor = catColor.split(' ').find(c => c.startsWith('border-')) || 'border-teal';
    return `border-l-4 ${borderColor}`;
  };

  // Helper to render individual category boxes
  const renderCategoryBox = (cat: { key: string; label: string; color: string; description?: string }, isMatrixCell = false) => {
    const catTasks = getTasksByCategory(cat.key);
    // Extract base color for subtle background
    const bgClass = cat.color.includes('bg-') ? cat.color.split(' ').find(c => c.startsWith('bg-')) : 'bg-white';
    const borderClass = cat.color.split(' ').find(c => c.startsWith('border-')) || 'border-gray-200';

    return (
      <div
        className={`
            h-full flex flex-col rounded-2xl border transition-all duration-300
            ${isMatrixCell ? 'p-3 shadow-sm hover:shadow-md' : 'p-4 shadow-sm bg-white'}
            ${isMatrixCell ? bgClass + '/30' : 'bg-white'} 
            ${isMatrixCell ? borderClass : 'border-gray-100'}
        `}
      >
        <div className="mb-4">
            <h3 className="font-bold text-lg flex items-center justify-between text-navy">
                <span className="flex items-center gap-2">
                    {!isMatrixCell && <div className={`w-2 h-2 rounded-full ${borderClass.replace('border-', 'bg-')}`}></div>}
                    {cat.label}
                </span>
                <span className={`text-xs font-bold px-2.5 py-1 rounded-lg ${isMatrixCell ? 'bg-white/60' : 'bg-gray-100'} text-gray-600`}>
                    {catTasks.length}
                </span>
            </h3>
            {cat.description && (
                <p className="text-xs text-gray-500 mt-2 leading-relaxed opacity-80">
                    {cat.description}
                </p>
            )}
        </div>

        <div className="space-y-3 overflow-y-auto flex-1 pr-1 custom-scrollbar min-h-[100px]">
            {catTasks.map((task) => (
            <TaskCard
                key={task.id}
                task={task}
                onToggle={handleToggle}
                onDelete={handleDelete}
                colorClass={getTaskColorClass(cat.color)}
            />
            ))}
            {catTasks.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-gray-400 border-2 border-dashed border-gray-300/30 rounded-xl p-4">
                    <span className="text-2xl opacity-30 mb-1">+</span>
                    <span className="text-xs opacity-60">فارغ</span>
                </div>
            )}
        </div>
      </div>
    );
  };

  const renderMatrix = () => {
    if (!config.matrixLabels) return renderKanban();

    return (
        <div className="h-full flex flex-col pb-6">
            {/* Mobile: Just list them */}
            <div className="md:hidden flex flex-col gap-4">
                 {config.categories.map(cat => (
                     <div key={cat.key} className="min-h-[200px]">
                         {renderCategoryBox(cat)}
                     </div>
                 ))}
            </div>

            {/* Desktop: Grid - CORRECTED LAYOUT: Labels on LEFT */}
            <div className="hidden md:grid gap-4 h-full" style={{
                gridTemplateColumns: '50px 1fr 1fr', // Auto for labels, then 2 equal cols
                gridTemplateRows: '50px 1fr 1fr' // Header height, then 2 equal rows
            }}>
                {/* 0,0 - Empty Corner */}
                <div className="col-start-1 row-start-1"></div>

                {/* Top Headers */}
                <div className="col-start-2 row-start-1 bg-navy/5 text-navy font-bold rounded-2xl flex items-center justify-center border border-navy/5">
                    {config.matrixLabels.x[1]} {/* Urgent */}
                </div>
                <div className="col-start-3 row-start-1 bg-navy/5 text-navy font-bold rounded-2xl flex items-center justify-center border border-navy/5">
                    {config.matrixLabels.x[0]} {/* Not Urgent */}
                </div>

                {/* Side Header 1 (Important - Top Row) */}
                <div className="col-start-1 row-start-2 bg-navy/5 text-navy font-bold rounded-2xl flex items-center justify-center border border-navy/5 writing-mode-vertical">
                    <span className="-rotate-90 whitespace-nowrap text-sm tracking-widest">{config.matrixLabels.y[0]}</span>
                </div>

                {/* Side Header 2 (Not Important - Bottom Row) */}
                <div className="col-start-1 row-start-3 bg-navy/5 text-navy font-bold rounded-2xl flex items-center justify-center border border-navy/5 writing-mode-vertical">
                    <span className="-rotate-90 whitespace-nowrap text-sm tracking-widest">{config.matrixLabels.y[1]}</span>
                </div>

                {/* Cells Placement */}
                <div className="col-start-2 row-start-2 overflow-hidden h-full">
                    {renderCategoryBox(config.categories[1], true)}
                </div>

                <div className="col-start-3 row-start-2 overflow-hidden h-full">
                    {renderCategoryBox(config.categories[0], true)}
                </div>

                <div className="col-start-2 row-start-3 overflow-hidden h-full">
                    {renderCategoryBox(config.categories[3], true)}
                </div>

                <div className="col-start-3 row-start-3 overflow-hidden h-full">
                    {renderCategoryBox(config.categories[2], true)}
                </div>

            </div>
        </div>
    );
  };

  const renderKanban = () => {
    return (
        <div className="flex flex-col md:flex-row gap-6 overflow-x-auto pb-6 h-full px-2">
          {config.categories.map((cat) => (
            <div
              key={cat.key}
              className="flex-shrink-0 w-full md:flex-1 md:min-w-[250px] h-full"
            >
               {renderCategoryBox(cat)}
            </div>
          ))}
        </div>
    );
  };

  const renderList = () => {
      return (
        <div className="space-y-6 max-w-4xl mx-auto pb-20">
            {config.categories.map((cat) => (
            <div key={cat.key} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 overflow-hidden relative group hover:shadow-md transition-shadow">
                <div className={`absolute top-0 left-0 bottom-0 w-1.5 ${cat.color.split(' ').find(c => c.startsWith('bg-'))?.replace('bg-', 'bg-') || 'bg-teal'}`}></div>
                <h3 className={`font-bold text-xl mb-3 flex items-center gap-3 text-navy pl-4`}>
                {cat.label}
                <span className="text-xs font-normal text-gray-400 bg-gray-50 px-2.5 py-1 rounded-full border border-gray-100">
                    {getTasksByCategory(cat.key).length} مهام
                </span>
                </h3>
                <p className="text-sm text-gray-500 mb-6 pl-4 max-w-2xl">{cat.description}</p>
                <div className="space-y-3 pl-0 md:pl-4">
                {getTasksByCategory(cat.key).map((task) => (
                    <TaskCard
                    key={task.id}
                    task={task}
                    onToggle={handleToggle}
                    onDelete={handleDelete}
                    colorClass={getTaskColorClass(cat.color)}
                    />
                ))}
                {getTasksByCategory(cat.key).length === 0 && (
                    <div className="flex flex-col items-center justify-center py-8 bg-gray-50/50 rounded-xl border border-dashed border-gray-200">
                        <p className="text-gray-400 text-sm">لا توجد مهام في هذه القائمة</p>
                    </div>
                )}
                </div>
            </div>
            ))}
        </div>
      );
  }

  const renderContent = () => {
    if (config.type === 'matrix') return renderMatrix();
    if (config.type === 'kanban') return renderKanban();
    return renderList();
  };

  return (
    <div className="h-full flex flex-col">
      <div className="mb-8 relative" ref={descriptionRef}>
        <div className="flex items-center gap-3">
            <h2 className="text-3xl font-extrabold text-navy flex items-center gap-3">
                {config.title}
            </h2>
            <button
                onClick={() => setShowDescription(!showDescription)}
                className={`
                    p-2 rounded-full transition-all duration-300
                    ${showDescription ? 'bg-teal text-white rotate-180' : 'text-teal hover:bg-teal/10 hover:scale-110'}
                `}
