                    <TaskCard
                    key={task.id}
                    task={task}
                    onToggle={handleToggle}
                    onDelete={handleDelete}
                    colorClass={getTaskColorClass(cat.color)}
                    />
                ))}
                {getTasksByCategory(cat.key).length === 0 && (
                    <div className="flex flex-col items-center justify-center py-8 bg-gray-50/50 rounded-xl border border-dashed border-gray-200">
                        <p className="text-gray-400 text-sm">لا توجد مهام في هذه القائمة</p>
                    </div>
                )}
                </div>
            </div>
            ))}
        </div>
      );
  }

  const renderContent = () => {
    if (config.type === 'matrix') return renderMatrix();
    if (config.type === 'kanban') return renderKanban();
    return renderList();
  };

  return (
    <div className="h-full flex flex-col">
      <div className="mb-8 relative">
        <div className="flex items-center gap-3">
            <h2 className="text-3xl font-extrabold text-navy flex items-center gap-3">
                {config.title}
            </h2>

            {/* 
              HOVER/TOUCH INTERACTION WRAPPER 
              - onMouseEnter/Leave handles Desktop Hover
              - onClick handles Mobile Tap (toggles state)
              - The container positioning ensures the popover is relative to this group
            */}
            <div 
                className="relative flex items-center"
                onMouseEnter={() => setShowDescription(true)}
                onMouseLeave={() => setShowDescription(false)}
            >
                <button
                    className={`
                        p-2 rounded-full transition-all duration-300 cursor-help
                        ${showDescription ? 'bg-teal text-white' : 'text-teal hover:bg-teal/10 hover:scale-110'}
                    `}
                    onClick={() => setShowDescription(!showDescription)} // Support click/tap as well for accessibility/mobile
                    aria-label="معلومات عن الطريقة"
                >
                    <HelpCircle size={24} />
                </button>

                {/* Popover Description */}
                <div className={`
                    absolute top-full right-0 mt-3 w-[300px] md:w-[500px] z-50
                    transition-all duration-300 ease-in-out origin-top-right
                    ${showDescription ? 'opacity-100 visible translate-y-0' : 'opacity-0 invisible -translate-y-2'}
                `}>
                    <div className="bg-white/95 backdrop-blur-xl p-6 rounded-2xl shadow-2xl border border-teal/20 text-navy relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-20 h-20 bg-teal/10 rounded-bl-full -mr-10 -mt-10"></div>

                        <h4 className="font-bold text-lg mb-2 flex items-center gap-2 text-teal">
                            <Info size={18} />
                            عن هذه الطريقة
                        </h4>
                        <p className="text-gray-600 leading-relaxed text-sm md:text-base">
                            {config.description}
                        </p>
                    </div>
                </div>
            </div>
        </div>
      </div>

      <div className="mb-10 w-full relative z-10">
        <SmartInput
          methodology={config.id}
          validCategories={config.categories.map((c) => c.key)}
          onTaskAdded={handleTaskAdded}
          exampleTask={config.exampleTask}
        />
      </div>

      <div className="flex-1 min-h-0 relative z-0">
        {renderContent()}
      </div>
    </div>
  );
};

